using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using UsbRecovery;

public static class UserSignatureRecoveryTests
{
    static string root;static int checks;
    static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
    static string Hash(string file){using(var source=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(source)).Replace("-","").ToLowerInvariant();}
    static byte[] Bytes(string text){return Encoding.ASCII.GetBytes(text);}
    static string Image(string name,byte[] bytes){string path=Path.Combine(root,name+".dd");File.WriteAllBytes(path,bytes);return path;}
    static string Output(string name){return Path.Combine(root,name+"-"+Guid.NewGuid().ToString("N").Substring(0,8));}
    static UserSignatureRule Fixed(){return new UserSignatureRule{Id="format",Name="Known uncommon format",Extension=".TEST",HeaderHex="41 42 43 44",FixedBytes=12};}
    static UserSignatureRule Footer(){return new UserSignatureRule{Id="footer",Name="Footer format",Extension="END",HeaderHex="41424344",FooterHex="454E4421",MaxBytes=1000,MinBytes=12};}
    static bool Io(Action action){try{action();return false;}catch(IOException){return true;}}
    static UserSignatureRecovery.Report Report(string output){return new JavaScriptSerializer().Deserialize<UserSignatureRecovery.Report>(File.ReadAllText(Path.Combine(output,"user-signatures.json")));}
    static void Verify(string image,string output,params byte[][] expected)
    {
        var report=Report(output);Check(report.Schema==1&&report.Status=="complete","complete schema report");Check(report.Files.Count==expected.Length&&report.Recovered==expected.Length,"only expected candidates");Check(report.InputBytes==new FileInfo(image).Length,"exact image size");Check(!Directory.GetFiles(output,"*.partial",SearchOption.AllDirectories).Any(),"no temporary partial published");
        for(int i=0;i<expected.Length;i++){
            var candidate=report.Files[i];string path=RecoveryCatalog.SafeFile(output,candidate.Path);byte[] result=File.ReadAllBytes(path);Check(result.SequenceEqual(expected[i]),"exact known independent bytes");Check(candidate.Bytes==expected[i].LongLength&&candidate.Sha256==Hash(path),"result hash and length bound to report");Check(candidate.Status=="signature_candidate"&&candidate.Note.Contains("unknown"),"signature never promoted to format validity/deletion");Check(candidate.Offset>=0&&candidate.Offset<=new FileInfo(image).Length-candidate.Bytes,"source mapping within image");byte[] source=new byte[candidate.Bytes];using(var input=File.OpenRead(image)){input.Position=candidate.Offset;Check(input.Read(source,0,source.Length)==source.Length,"source mapping readable");}Check(source.SequenceEqual(result),"source extent exact bytes");Check(candidate.Path.StartsWith("user-signatures/",StringComparison.Ordinal)&&!candidate.Path.Contains(".."),"safe flat relative output");
        }
    }
    static void Positive()
    {
        byte[] payload=Bytes("ABCDcontents"),data=new byte[400];payload.CopyTo(data,31);payload.CopyTo(data,217);string image=Image("fixed",data),before=Hash(image),output=Output("fixed");
        Check(UserSignatureRecovery.Recover(image,output,new[]{Fixed()},CancellationToken.None,null)==2,"fixed-size two candidates");Verify(image,output,payload,payload);Check(Hash(image)==before,"fixed input hash unchanged");Check(Report(output).Rules[0].Extension=="test"&&Report(output).Rules[0].HeaderHex=="41 42 43 44","rules normalize without mutating source");
        var offset=Fixed();offset.Id="offset";offset.HeaderOffset=7;offset.FixedBytes=19;offset.Name="Offset header";data=new byte[120];byte[] whole=Bytes("prefix!ABCDcontents");whole.CopyTo(data,9);image=Image("offset",data);output=Output("offset");Check(UserSignatureRecovery.Recover(image,output,new[]{offset},CancellationToken.None,null)==1,"header at nonzero logical offset");Verify(image,output,whole);Check(Report(output).Files[0].Offset==9&&Report(output).Files[0].HeaderOffset==7,"logical origin differs from header position");
        data=new byte[1024*1024+270];payload.CopyTo(data,1024*1024-2);payload.CopyTo(data,1024*1024+201);image=Image("boundary",data);output=Output("boundary");Check(UserSignatureRecovery.Recover(image,output,new[]{Fixed()},CancellationToken.None,null)==2,"headers across block boundary and following block exactly once");Verify(image,output,payload,payload);Check(Report(output).Files.Select(x=>x.Offset).Distinct().Count()==2,"boundary does not duplicate candidates");
        payload=Bytes("ABCDrecipe dataEND!");data=new byte[130];payload.CopyTo(data,23);Bytes("END!").CopyTo(data,100);image=Image("footer",data);output=Output("footer");Check(UserSignatureRecovery.Recover(image,output,new[]{Footer()},CancellationToken.None,null)==1,"first valid bounded footer");Verify(image,output,payload);Check(Report(output).Files[0].Boundary=="first_matching_footer","heuristic boundary explicit");
        var overlap=Footer();overlap.FooterHex="41424142";overlap.MinBytes=8;payload=Bytes("ABCDxxABAABAB");image=Image("overlap",payload);output=Output("overlap");Check(UserSignatureRecovery.Recover(image,output,new[]{overlap},CancellationToken.None,null)==1,"overlapping footer prefix handled");Verify(image,output,payload);
        data=new byte[1024*1024+100];int start=1024*1024-9;payload=Bytes("ABCDrecipe dataEND!");payload.CopyTo(data,start);image=Image("footer-boundary",data);output=Output("footer-boundary");Check(UserSignatureRecovery.Recover(image,output,new[]{Footer()},CancellationToken.None,null)==1,"footer across source block boundary");Verify(image,output,payload);
        var unicode=Fixed();unicode.Id="unicode";unicode.Name="Редкий формат 🥟";payload=Bytes("ABCDcontents");image=Image("unicode",payload);output=Output("unicode");Check(UserSignatureRecovery.Recover(image,output,new[]{unicode},CancellationToken.None,null)==1,"Unicode label retained");Check(Report(output).Files[0].RuleName==unicode.Name,"Unicode display name exact");
    }
    static void Negatives()
    {
        string image=Image("truncated",Bytes("xABCDshort")),output=Output("truncated");Check(UserSignatureRecovery.Recover(image,output,new[]{Fixed()},CancellationToken.None,null)==0,"fixed-length truncated body rejected");Check(Report(output).Skipped.ContainsKey("truncated_fixed_size"),"truncation diagnosed");Verify(image,output);
        image=Image("footer-missing",Bytes("ABCDdata but no footer"));output=Output("footer-missing");Check(UserSignatureRecovery.Recover(image,output,new[]{Footer()},CancellationToken.None,null)==0,"footer absent not guessed to EOF");Check(Report(output).Skipped.ContainsKey("footer_missing"),"missing end diagnosed");Verify(image,output);
        var footer=Footer();footer.MaxBytes=12;image=Image("footer-too-far",Bytes("ABCDlong-long-dataEND!"));output=Output("footer-too-far");Check(UserSignatureRecovery.Recover(image,output,new[]{footer},CancellationToken.None,null)==0,"footer beyond max bytes cannot expand bound");Verify(image,output);
        footer=Footer();footer.MinBytes=20;image=Image("footer-too-early",Bytes("ABCDEND!stuff"));output=Output("footer-too-early");Check(UserSignatureRecovery.Recover(image,output,new[]{footer},CancellationToken.None,null)==0,"footer before minimum excluded");Verify(image,output);
        var offset=Fixed();offset.HeaderOffset=3;image=Image("negative-start",Bytes("ABCDcontents"));output=Output("negative-start");Check(UserSignatureRecovery.Recover(image,output,new[]{offset},CancellationToken.None,null)==0,"negative logical start rejected");Check(Report(output).Skipped.ContainsKey("negative_start"),"negative start diagnosed");
        image=Image("blank",new byte[1024]);output=Output("blank");Check(UserSignatureRecovery.Recover(image,output,new[]{Fixed(),Footer()},CancellationToken.None,null)==0,"no false outputs without header");Verify(image,output);
        image=Image("sameheader",Bytes("ABCDcontents"));output=Output("sameheader");var second=Fixed();second.Id="alternate";second.Extension="other";Check(UserSignatureRecovery.Recover(image,output,new[]{Fixed(),second},CancellationToken.None,null)==2,"rules with same header retain provenance separately");Check(Report(output).Files.Select(x=>x.RuleId).Distinct().Count()==2,"rule IDs preserved for same bytes");
    }
    static void Validation()
    {
        var original=Fixed();var normalized=UserSignatureRecovery.Validate(new[]{original});normalized[0].HeaderHex="AA BB CC DD";Check(original.HeaderHex=="41 42 43 44","validation clones mutable rules");
        var bad=new List<UserSignatureRule>();foreach(string header in new[]{"", "ABC", "GG HH 03 04", "00 00 00 00", "00 01 00 01", "01 02 03",new string('A',514)}){var item=Fixed();item.HeaderHex=header;bad.Add(item);}foreach(string id in new[]{"", "../escape", "name.txt", new string('a',41),"a:b"}){var item=Fixed();item.Id=id;bad.Add(item);}foreach(string ext in new[]{"../exe", "bin:ads", "bin.exe", "with space", new string('x',13)}){var item=Fixed();item.Extension=ext;bad.Add(item);}
        var rule=Fixed();rule.HeaderOffset=-1;bad.Add(rule);rule=Fixed();rule.HeaderOffset=4097;bad.Add(rule);rule=Fixed();rule.MinBytes=3;bad.Add(rule);rule=Fixed();rule.MaxBytes=3;bad.Add(rule);rule=Fixed();rule.FixedBytes=UserSignatureRecovery.MaximumFileBytes+1;bad.Add(rule);rule=Fixed();rule.FixedBytes=0;bad.Add(rule);rule=Footer();rule.FixedBytes=12;bad.Add(rule);rule=Footer();rule.FooterHex="0102";bad.Add(rule);rule=Footer();rule.MaxBytes=7;bad.Add(rule);rule=Fixed();rule.Name="bad\0name";bad.Add(rule);rule=Fixed();rule.FixedBytes=-1;bad.Add(rule);
        foreach(var value in bad)Check(Io(()=>UserSignatureRecovery.Validate(new[]{value})),"invalid rule rejected: "+value.Id+" "+value.HeaderHex);
        Check(Io(()=>UserSignatureRecovery.Validate(null)),"null rules rejected");Check(Io(()=>UserSignatureRecovery.Validate(new UserSignatureRule[0])),"empty rules rejected");Check(Io(()=>UserSignatureRecovery.Validate(new UserSignatureRule[]{null})),"null row rejected");Check(Io(()=>UserSignatureRecovery.Validate(new[]{Fixed(),Fixed()})),"duplicate IDs rejected");Check(Io(()=>UserSignatureRecovery.Validate(Enumerable.Range(0,33).Select(i=>new UserSignatureRule{Id="x"+i,Name="x",Extension="bin",HeaderHex="01020304",FixedBytes=4}))),"rule count bounded");
        string valid="[{\"Id\":\"sample\",\"Name\":\"Sample\",\"Extension\":\"x\",\"HeaderHex\":\"01020304\",\"FixedBytes\":4}]";Check(UserSignatureRecovery.ParseRules(valid).Count==1,"strict JSON array accepted");
        foreach(string json in new[]{"null","{}","[null]","[true]","[{}]","[",valid.Replace("\"FixedBytes\":4","\"FixedBytes\":4.0"),valid.Replace("\"FixedBytes\":4","\"FixedBytes\":true"),valid.Replace("\"FixedBytes\":4","\"FixedBytes\":\"4\""),valid.Replace("\"FixedBytes\":4","\"FixedBytes\":4,\"Execute\":\"anything\""),valid.Replace("\"Name\":\"Sample\"","\"Name\":7"),valid.Replace("\"FixedBytes\":4","\"FixedBytes\":4,\"FixedBytes\":8"),valid.Replace("\"Id\":\"sample\"","\"Id\":\"sample\",\"\\u0049d\":\"other\""),new string(' ',131073)})Check(Io(()=>UserSignatureRecovery.ParseRules(json)),"invalid JSON/type/unknown/duplicate field rejected");
    }
    static void GuardsAndLimits()
    {
        string image=Image("guard",Bytes("ABCDcontents")),before=Hash(image),output=Output("guard");var cancelled=new CancellationTokenSource();cancelled.Cancel();bool stopped=false;try{UserSignatureRecovery.Recover(image,output,new[]{Fixed()},cancelled.Token,null);}catch(OperationCanceledException){stopped=true;}Check(stopped&&!Directory.Exists(output),"pre-start cancellation publishes nothing");
        foreach(string path in new[]{@"\\.\PhysicalDrive0",@"\\server\share\image.dd",image+":stream",@"\\?\C:\image.dd"}){output=Output("path");Check(Io(()=>UserSignatureRecovery.Recover(path,output,new[]{Fixed()},CancellationToken.None,null)),"nonregular/nonlocal input rejected");Check(!Directory.Exists(output),"invalid source creates no output");}
        output=Output("existing");Directory.CreateDirectory(Path.Combine(output,"user-signatures"));File.WriteAllText(Path.Combine(output,"user-signatures","keep"),"preserve");Check(Io(()=>UserSignatureRecovery.Recover(image,output,new[]{Fixed()},CancellationToken.None,null)),"existing output not overwritten");Check(File.ReadAllText(Path.Combine(output,"user-signatures","keep"))=="preserve","existing result unchanged");
        output=Output("collision");Directory.CreateDirectory(output);string colliding=Path.Combine(output,"user-signatures.json");File.Copy(image,colliding);Check(Io(()=>UserSignatureRecovery.Recover(colliding,output,new[]{Fixed()},CancellationToken.None,null)),"source cannot collide with manifest");Check(Hash(colliding)==before,"manifest/source collision unchanged");
        string partial=image+".partial";File.Copy(image,partial);output=Output("partial");Check(Io(()=>UserSignatureRecovery.Recover(partial,output,new[]{Fixed()},CancellationToken.None,null))&&!Directory.Exists(output),"unfinished image not treated as complete source");
        output=Output("cancel-progress");image=Image("cancel-progress",new byte[1024*1024+7]);cancelled=new CancellationTokenSource();stopped=false;try{UserSignatureRecovery.Recover(image,output,new[]{Fixed()},cancelled.Token,(a,b)=>cancelled.Cancel());}catch(OperationCanceledException){stopped=true;}Check(stopped&&Report(output).Status=="cancelled","in-progress cancellation checkpoint");Check(!Directory.GetFiles(output,"*.partial",SearchOption.AllDirectories).Any(),"cancelled scan no partial file");
        var footer=Footer();footer.MaxBytes=12;footer.MinBytes=8;byte[] repeated=Enumerable.Range(0,UserSignatureRecovery.MaximumCandidates+1).SelectMany(i=>Bytes("ABCDxxxx")).ToArray();image=Image("candidate-limit",repeated);before=Hash(image);output=Output("candidate-limit");Check(Io(()=>UserSignatureRecovery.Recover(image,output,new[]{footer},CancellationToken.None,null)),"common header scan capped");var report=Report(output);Check(report.Status=="limited"&&report.Candidates==UserSignatureRecovery.MaximumCandidates+1,"candidate limit diagnosed as incomplete");Check(report.Recovered==0&&Hash(image)==before,"limit no forged files or source mutation");
        // The default footer-work cap can be reached using a small ordinary
        // source; no sparse or physical disk operation is required.
        footer=Footer();footer.MaxBytes=1024*1024;byte[] work=new byte[1024*1024+32];for(int i=0;i<1024;i++)Bytes("ABCD").CopyTo(work,i*8);image=Image("footer-work-limit",work);output=Output("footer-work-limit");Check(Io(()=>UserSignatureRecovery.Recover(image,output,new[]{footer},CancellationToken.None,null)),"footer rescans consume bounded shared budget");report=Report(output);Check(report.Status=="limited"&&report.FooterWorkBytes<=UserSignatureRecovery.MaximumFooterWorkBytes&&report.Recovered==0,"work budget cannot masquerade as complete");
        var longPrefix=Fixed();longPrefix.HeaderHex=String.Join(" ",Enumerable.Repeat("41",253).Concat(new[]{"42","43","44"}));longPrefix.FixedBytes=256;image=Image("near-match-work-limit",Enumerable.Repeat((byte)65,3*1024*1024).ToArray());output=Output("near-match-work-limit");Check(Io(()=>UserSignatureRecovery.Recover(image,output,new[]{longPrefix},CancellationToken.None,null)),"near-matching long prefixes have explicit comparison cap");report=Report(output);Check(report.Status=="limited"&&report.HeaderWorkBytes<=UserSignatureRecovery.MaximumHeaderWorkBytes+1&&report.Recovered==0,"header CPU budget prevents unconstrained near-match work");
    }
    public static int Main(string[] args)
    {
        try{string project=Path.GetFullPath(args[0]);root=Path.Combine(project,".build","user-signature-tests-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(root);Positive();Negatives();Validation();GuardsAndLimits();Console.WriteLine("PASS UserSignatureRecovery: "+checks+" checks; literal fixed/footer boundaries, block boundaries, offsets, normalization/invalid rules, caps/cancellation/path guards/source SHA; candidates never asserted intact. Synthetic regular files only. "+root);return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
